starter.versions.tf:
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

starter.variables.tf:
variable "bucket_names" {
  description = "Map of logical name to bucket name."
  type        = map(string)
  default = {
    logs   = "arena-tutorial-logs"
    assets = "arena-tutorial-assets"
  }
}

variable "aws_region" {
  description = "Region for the demo resources."
  type        = string
  default     = "us-east-1"
}

starter.main.tf:
provider "aws" {
  region = var.aws_region
}

resource "aws_s3_bucket" "this" {
  # TODO - Create named instances.
  # Iterate over the map and use the current entry value as the bucket name.
}

starter.outputs.tf:
output "bucket_ids" {
  value = { for name, bucket in aws_s3_bucket.this : name => bucket.id }
}
